      const snap = await svc.snapshot(sku);
      assert.equal(snap.reserved, held[sku].reserved, `${sku} reserved`);
      assert.equal(snap.sold, held[sku].sold, `${sku} sold`);
      assert.equal(snap.stock, initial[sku] - held[sku].sold, `${sku} stock`);
      assert.ok(snap.stock - snap.reserved >= 0, `${sku} available went negative`);
