'use strict';

/**
 * Mutual exclusion per key. Callers that share a key run one at a time, in
 * arrival order; callers with no key in common never wait for each other.
 *
 * Only callers in this process are coordinated. The store offers no atomic
 * compare-and-set, so the lock cannot extend across processes.
 */
class KeyedLock {
  constructor() {
    // key -> promise that resolves when the most recent claimant releases the key
    this.tails = new Map();
  }

  /** Keys currently held or waited on. */
  get size() {
    return this.tails.size;
  }

  /**
   * Run `fn` while holding every key in `keys` (which must be distinct), then
   * release them whether `fn` resolves or rejects. Keys are taken in sorted
   * order, so callers locking overlapping sets cannot deadlock.
   */
  async withKeys(keys, fn) {
    const releases = [];
    try {
      // Sequential on purpose: holding a key while waiting for the next one in
      // sorted order is what rules out deadlock.
      for (const key of [...keys].sort()) {
        releases.push(await this.acquire(key));
      }
      return await fn();
    } finally {
      for (const release of releases) {
        release();
      }
    }
  }

  async acquire(key) {
    const previous = this.tails.get(key);
    let release;
    const tail = new Promise(resolve => {
      release = resolve;
    });
    this.tails.set(key, tail);
    if (previous) {
      await previous;
    }
    return () => {
      // Forget the key once nobody is queued behind us, so the map stays
      // bounded by the keys in use rather than every SKU and order ever seen.
      if (this.tails.get(key) === tail) {
        this.tails.delete(key);
      }
      release();
    };
  }
}

module.exports = { KeyedLock };

