'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { KeyedLock } = require('../src/keyed-lock');

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

function gate() {
  let open;
  const opened = new Promise(resolve => {
    open = resolve;
  });
  return { opened, open };
}

describe('KeyedLock', () => {
  it('runs holders of one key one at a time, in arrival order', async () => {
    const lock = new KeyedLock();
    const events = [];
    const holder = name => lock.withKeys(['k'], async () => {
      events.push(`${name} in`);
      await tick();
      await tick();
      events.push(`${name} out`);
      return name;
    });
    assert.deepEqual(await Promise.all([holder('a'), holder('b'), holder('c')]), ['a', 'b', 'c']);
    assert.deepEqual(events, ['a in', 'a out', 'b in', 'b out', 'c in', 'c out']);
  });

  it('does not make holders of different keys wait', async () => {
    const lock = new KeyedLock();
    const { opened, open } = gate();
    const blocked = lock.withKeys(['a'], () => opened);
    assert.equal(await lock.withKeys(['b'], async () => 'done'), 'done');
    open();
    await blocked;
  });

  it('releases the keys when fn throws', async () => {
    const lock = new KeyedLock();
    await assert.rejects(lock.withKeys(['k'], async () => {
      throw new Error('boom');
    }), /boom/);
    assert.equal(await lock.withKeys(['k'], async () => 'next'), 'next');
    assert.equal(lock.size, 0);
  });

  it('does not deadlock when callers list overlapping keys in opposite orders', async () => {
    const lock = new KeyedLock();
    const holder = keys => lock.withKeys(keys, async () => {
      await tick();
      return keys.join('');
    });
    const both = Promise.all([holder(['a', 'b']), holder(['b', 'a']), holder(['b', 'c', 'a'])]);
    let timer;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new Error('deadlock')), 1000);
    });
    assert.deepEqual(await Promise.race([both, timeout]).finally(() => clearTimeout(timer)), ['ab', 'ba', 'bca']);
  });

  it('forgets keys once nobody holds or waits for them', async () => {
    const lock = new KeyedLock();
    const { opened, open } = gate();
    const held = lock.withKeys(['a', 'b'], () => opened);
    const queued = lock.withKeys(['a'], async () => {});
    await tick();
    assert.equal(lock.size, 2);
    open();
    await Promise.all([held, queued]);
    await Promise.all(Array.from({ length: 1000 }, (_, i) => lock.withKeys([`sku-${i}`], tick)));
    assert.equal(lock.size, 0);
  });
});

