  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  /**
   * Apply `change` to the counters of every SKU in the order, then write the
   * order record, all while holding the SKU locks. The caller holds the
   * order's lock. Every SKU is read and checked before anything is written,
   * so a `change` that throws leaves the store untouched.
   */
  async #writeOrder(order, previousOrder, change) {
    return this.#locks.withKeys(order.items.map(({ sku }) => skuKey(sku)), async () => {
      const current = await Promise.all(order.items.map(({ sku }) => this.getItem(sku)));
      const writes = order.items.map(({ sku, qty }, i) => ({
        key: skuKey(sku),
        previous: current[i],
        value: change(current[i], qty, sku)
      }));
      // Last, so the record never claims SKU changes that were rolled back.
      writes.push({ key: orderKey(order.orderId), previous: previousOrder, value: order });
      await this.#writeAll(writes);
      return toReservation(order);
    });
  }

  /**
   * Write each value in turn. If a write fails, put back the values already
   * written and rethrow, so the call changes nothing. Only the last write may
   * have no `previous` value, because it is never rolled back.
   */
  async #writeAll(writes) {
    const written = [];
