'use strict';

// Regression tests for INC-5521. Each describe block reproduces one symptom
// from ISSUE.md; most need concurrent calls, which the hand-driven checkout
// flow and the original unit tests never made.

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

async function service(stock, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

// Starts call i after i event-loop turns, so later calls land while earlier
// ones are part-way through, the way a retry after a client timeout does.
function staggered(count, call) {
  return Array.from({ length: count }, async (_, i) => {
    for (let turn = 0; turn < i; turn++) {
      await tick();
    }
    return call(i);
  });
}

// Fails the test instead of hanging it when a call is blocked behind another.
function withinMs(promise, ms, what) {
  let timer;
  const timeout = new Promise((_, reject) => {
    timer = setTimeout(() => reject(new Error(`${what} did not finish within ${ms}ms`)), ms);
  });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

// Deterministic PRNG so the stress test replays the same interleaving.
function mulberry32(seed) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Store whose calls take a random number of extra event-loop turns, so
// concurrent calls interleave in more orders than the lockstep Store gives.
class JitterStore {
  constructor(random) {
    this.inner = new Store();
    this.random = random;
  }

  async jitter() {
    const turns = Math.floor(this.random() * 4);
    for (let i = 0; i < turns; i++) {
      await tick();
    }
  }

  async get(key) {
    await this.jitter();
    return this.inner.get(key);
  }

  async set(key, value) {
    await this.jitter();
    return this.inner.set(key, value);
  }

  async keys(prefix) {
    await this.jitter();
    return this.inner.keys(prefix);
  }
}

describe('oversold stock: concurrent reserves of one sku', () => {
  it('holds no more units than are in stock', async () => {
    const svc = await service({ 'sneaker-limited': 250 });
    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
    );
    const rejected = results.filter(r => r.status === 'rejected');
    assert.equal(results.length - rejected.length, 250);
    assert.equal(rejected.length, 13);
    for (const { reason } of rejected) {
      assert.ok(reason instanceof InsufficientStockError, `unexpected error: ${reason}`);
    }
    assert.deepEqual(await svc.snapshot('sneaker-limited'), { sku: 'sneaker-limited', stock: 250, reserved: 250, sold: 0 });
  });

  it('does not lose stock added while reserves are in flight', async () => {
    const svc = await service({ widget: 10 });
    await Promise.all([
      ...Array.from({ length: 10 }, () => svc.addStock('widget', 1)),
      ...Array.from({ length: 10 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'widget', qty: 1 }]))
    ]);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 20, reserved: 10, sold: 0 });
  });

  it('holds when service instances share one store', async () => {
    const store = new Store();
    const workers = Array.from({ length: 4 }, () => new InventoryService({ store }));
    await workers[0].addStock('sneaker-limited', 250);
    const results = await Promise.allSettled(
      Array.from({ length: 263 }, (_, i) =>
        workers[i % workers.length].reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }])
      )
    );
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 250);
    assert.equal(await workers[0].available('sneaker-limited'), 0);
  });
});

describe('double holds: retried reserve for one order', () => {
  it('holds stock once when retries overlap the first attempt', async () => {
    const svc = await service({ widget: 10 });
    const attempts = await Promise.all(staggered(5, () => svc.reserve('o1', [{ sku: 'widget', qty: 2 }])));
    for (const reservation of attempts) {
      assert.deepEqual(reservation, { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 2 }] });
    }
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 2, sold: 0 });
  });
});

describe('stuck bundle holds: reserve is all items or none', () => {
  it('holds nothing when a later item is short', async () => {
    const svc = await service({ shoe: 5, sock: 1 });
    await assert.rejects(
      svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'sock', qty: 2 }]),
      err => err instanceof InsufficientStockError && err.sku === 'sock' && err.available === 1
    );
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('sock'), 1);
    await assert.rejects(svc.commit('o1'), UnknownOrderError);
  });

  it('holds nothing when a later item is an unknown sku', async () => {
    const svc = await service({ shoe: 5 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'nope', qty: 1 }]), UnknownSkuError);
    assert.equal(await svc.available('shoe'), 5);
  });

  it('lets a rejected order be retried once stock arrives', async () => {
    const svc = await service({ shoe: 5, sock: 1 });
    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'sock', qty: 2 }]), InsufficientStockError);
    await svc.addStock('sock', 1);
    const reservation = await svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'sock', qty: 2 }]);
    assert.equal(reservation.status, 'reserved');
    assert.equal(await svc.available('shoe'), 3);
    assert.equal(await svc.available('sock'), 0);
  });

  it('rolls back earlier holds when a store write fails', async () => {
    const store = new Store();
    const svc = await service({ shoe: 5, sock: 5 }, { store });
    const set = store.set.bind(store);
    let failNext = true;
    store.set = async (key, value) => {
      if (key === 'sku:sock' && failNext) {
        failNext = false;
        throw new Error('store timeout');
      }
      return set(key, value);
    };
    await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'sock', qty: 2 }]), /store timeout/);
    assert.equal(await svc.available('shoe'), 5);
    assert.equal(await svc.available('sock'), 5);
    await assert.rejects(svc.release('o1'), UnknownOrderError);
  });

  it('does not deadlock or oversell when bundles list skus in opposite orders', async () => {
    const svc = await service({ a: 10, b: 10 });
    const results = await withinMs(
      Promise.allSettled(
        Array.from({ length: 20 }, (_, i) => {
          const items = i % 2 === 0 ? [{ sku: 'a', qty: 1 }, { sku: 'b', qty: 1 }] : [{ sku: 'b', qty: 1 }, { sku: 'a', qty: 1 }];
          return svc.reserve(`order-${i}`, items);
        })
      ),
      2000,
      'opposite-order bundles'
    );
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 10);
    assert.deepEqual(await svc.snapshot('a'), { sku: 'a', stock: 10, reserved: 10, sold: 0 });
    assert.deepEqual(await svc.snapshot('b'), { sku: 'b', stock: 10, reserved: 10, sold: 0 });
  });
});

describe('negative reserved: releasing units that are no longer held', () => {
  it('expire leaves committed orders alone', async () => {
    let t = 0;
    const svc = await service({ widget: 5 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    await svc.commit('o1');
    t = 5000;
    assert.deepEqual(await svc.expire(), []);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 3, reserved: 0, sold: 2 });
    assert.equal((await svc.commit('o1')).status, 'committed');
  });

  it('release rejects a committed order', async () => {
    const svc = await service({ widget: 5 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    await svc.commit('o1');
    await assert.rejects(
      svc.release('o1'),
      err => err instanceof OrderStateError && err.status === 'committed' && err.orderId === 'o1'
    );
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 3, reserved: 0, sold: 2 });
  });

  it('concurrent releases and expire return the units once', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    t = 5000;
    const [first, second, expired] = await Promise.all([svc.release('o1'), svc.release('o1'), svc.expire()]);
    assert.equal(first.status, 'released');
    assert.equal(second.status, 'released');
    assert.deepEqual(expired, []);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  });

  it('expire reports only the orders it released', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 1 }]);
    await svc.reserve('o2', [{ sku: 'widget', qty: 1 }]);
    await svc.release('o1');
    t = 5000;
    assert.deepEqual(await svc.expire(), ['o2']);
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
  });
});

describe('inflated sold: overlapping commits and releases of one order', () => {
  it('concurrent commits sell the units once', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    const commits = await Promise.all(staggered(5, () => svc.commit('o1')));
    for (const reservation of commits) {
      assert.equal(reservation.status, 'committed');
    }
    assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
  });

  it('a commit racing a release lets exactly one of them win', async () => {
    const svc = await service({ widget: 10 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    const [commit, release] = await Promise.allSettled([svc.commit('o1'), svc.release('o1')]);
    const won = [commit, release].filter(r => r.status === 'fulfilled');
    assert.equal(won.length, 1);
    const lost = commit.status === 'rejected' ? commit : release;
    assert.ok(lost.reason instanceof OrderStateError, `unexpected error: ${lost.reason}`);
    const expected = commit.status === 'fulfilled'
      ? { sku: 'widget', stock: 8, reserved: 0, sold: 2 }
      : { sku: 'widget', stock: 10, reserved: 0, sold: 0 };
    assert.deepEqual(await svc.snapshot('widget'), expected);
  });

  it('expire racing a commit either expires the order or lets it commit, not both', async () => {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    t = 5000;
    const [expired, commit] = await Promise.allSettled([svc.expire(), svc.commit('o1')]);
    assert.equal(expired.status, 'fulfilled');
    if (commit.status === 'fulfilled') {
      assert.deepEqual(expired.value, []);
      assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 8, reserved: 0, sold: 2 });
    } else {
      assert.ok(commit.reason instanceof OrderStateError);
      assert.deepEqual(expired.value, ['o1']);
      assert.deepEqual(await svc.snapshot('widget'), { sku: 'widget', stock: 10, reserved: 0, sold: 0 });
    }
  });
});

describe('isolation: calls that share no sku and no order', () => {
  it('do not wait for each other', async () => {
    const store = new Store();
    const svc = await service({ slow: 5, fast: 5 }, { store });
    await svc.reserve('fast-old', [{ sku: 'fast', qty: 1 }]);

    let openGate;
    const gate = new Promise(resolve => { openGate = resolve; });
    let blocked;
    const reached = new Promise(resolve => { blocked = resolve; });
    const get = store.get.bind(store);
    store.get = async key => {
      if (key === 'sku:slow') {
        blocked();
        await gate;
      }
      return get(key);
    };

    const slow = svc.reserve('slow-order', [{ sku: 'slow', qty: 1 }]);
    await reached;
    await withinMs(
      (async () => {
        await svc.addStock('fast', 1);
        await svc.reserve('fast-new', [{ sku: 'fast', qty: 1 }]);
        await svc.commit('fast-new');
        await svc.release('fast-old');
        await svc.available('fast');
      })(),
      2000,
      'calls on an unrelated sku'
    );
    openGate();
    assert.equal((await slow).status, 'reserved');
    assert.deepEqual(await svc.snapshot('fast'), { sku: 'fast', stock: 5, reserved: 0, sold: 1 });
  });
});

describe('stress: mixed concurrent workload', () => {
  it('keeps every counter consistent with the orders in the store', async () => {
    const random = mulberry32(5521);
    const store = new JitterStore(random);
    let t = 0;
    const initial = { a: 40, b: 25, c: 60 };
    const svc = await service(initial, { store, now: () => t, reservationTtlMs: 1000 });
    const skus = Object.keys(initial);

    const orders = Array.from({ length: 150 }, (_, i) => {
      const count = 1 + Math.floor(random() * skus.length);
      const picked = [...skus].sort(() => random() - 0.5).slice(0, count);
      return { orderId: `order-${i}`, items: picked.map(sku => ({ sku, qty: 1 + Math.floor(random() * 3) })) };
    });

    const expected = [InsufficientStockError, OrderStateError];
    const tolerate = promise => promise.catch(err => {
      if (!expected.some(type => err instanceof type)) {
        throw err;
      }
    });

    const workload = orders.map(async ({ orderId, items }) => {
      const retries = 1 + Math.floor(random() * 2);
      await Promise.all(Array.from({ length: retries }, () => tolerate(svc.reserve(orderId, items))));
      const action = random();
      if (action < 0.35) {
        await Promise.all([tolerate(svc.commit(orderId)), tolerate(svc.commit(orderId))]);
      } else if (action < 0.55) {
        await Promise.all([tolerate(svc.release(orderId)), tolerate(svc.release(orderId))]);
      } else if (action < 0.75) {
        await Promise.all([tolerate(svc.commit(orderId)), tolerate(svc.release(orderId))]);
      }
    }).map(p => p.catch(err => {
      // An order rejected at reserve time has no record; commit or release then throws UnknownOrderError.
      if (!(err instanceof UnknownOrderError)) {
        throw err;
      }
    }));

    const sweeps = (async () => {
      await tick();
      t = 5000;
      await Promise.all([svc.expire(), svc.expire()]);
    })();

    await Promise.all([...workload, sweeps]);

    const held = Object.fromEntries(skus.map(sku => [sku, { reserved: 0, sold: 0 }]));
    for (const key of await store.keys('order:')) {
      const order = await store.get(key);
      for (const { sku, qty } of order.items) {
        if (order.status === 'reserved') held[sku].reserved += qty;
        if (order.status === 'committed') held[sku].sold += qty;
      }
    }
    for (const sku of skus) {
      const snap = await svc.snapshot(sku);
      assert.equal(snap.reserved, held[sku].reserved, `${sku} reserved`);
      assert.equal(snap.sold, held[sku].sold, `${sku} sold`);
      assert.equal(snap.stock, initial[sku] - held[sku].sold, `${sku} stock`);
      assert.ok(snap.stock - snap.reserved >= 0, `${sku} available went negative`);
    }
  });
});
